"""Print the dependency closure of the pipeline's real roots, from the box venv."""
import importlib.metadata as md
import re
import sys
from packaging.requirements import Requirement

ROOTS = [
    # imported by pipeline/
    "torch", "transformers", "trl", "peft", "datasets", "numpy", "scipy",
    "matplotlib", "pyyaml", "pytest", "uvicorn",
    # generation + quantization backends the configs select
    "vllm", "bitsandbytes", "accelerate",
    # OpenEnv env servers (installed from the clone, their deps must be pinned)
    "openenv", "reasoning-gym", "browsergym-core", "browsergym-miniwob",
    "playwright",
]


def canon(n):
    return re.sub(r"[-_.]+", "-", n).lower()


dists = {}
for d in md.distributions():
    name = d.metadata["Name"]
    if name:
        dists.setdefault(canon(name), d)

seen, missing, queue = set(), [], [canon(r) for r in ROOTS]
while queue:
    n = queue.pop()
    if n in seen:
        continue
    seen.add(n)
    d = dists.get(n)
    if d is None:
        missing.append(n)
        continue
    for raw in d.requires or []:
        req = Requirement(raw)
        if req.marker and not req.marker.evaluate({"extra": ""}):
            continue
        queue.append(canon(req.name))

print("MISSING_ROOTS", sorted(missing), file=sys.stderr)
for n in sorted(seen):
    if n in dists:
        print(f"{n}=={dists[n].version}")

